51	interface MatrixBodyCornerBaseOption extends MatrixCellStyleOption {
52	    /**
53	     * Only specify some special cell definitions.
54	     * It can represent both body cells and top-left corner cells.
55	     *
56	     * [body/corner cell locating]:
57	     *  The rule is uniformly applied, such as, in `matrix.dataToPoint`
58	     *  and `matrix.dataToLayout` and `xxxComponent.coord`.
59	     *  Suppose the matrix.x/y dimensions (header) are defined as:
60	     *  matrix: {
61	     *      x: [{ value: 'Xa0', children: ['Xb0', 'Xb1'] }, 'Xa1'],
62	     *      y: [{ value: 'Ya0', children: ['Yb0', 'Yb1'] }],
63	     *  }
64	     *  -----------------------------------------
65	     *  |       |       |     Xa0       |       |
66	     *  |-------+-------+---------------|  Xa1  |
67	     *  |cornerQ|cornerP|  Xb0  |  Xb1  |       |
68	     *  |-------+-------+-------+-------+--------
69	     *  |       |  Yb0  | bodyR | bodyS |       |
70	     *  |  Ya0  |-------+-------+---------------|
71	     *  |       |  Yb1  |       |     bodyT     |
72	     *  |---------------|------------------------
73	     *  "Locator number" (`MatrixXYLocator`):
74	     *    The term `locator` refers to a integer number to locate cells on x or y direction.
75	     *    Use the top-left cell of the body as the origin point (0, 0),
76	     *      the non-negative locator indicates the right/bottom of the origin point;
77	     *      the negative locator indicates the left/top of the origin point.
78	     *  "Ordinal number" (`OrdinalNumber`):
79	     *    This term follows the same meaning as that in category axis of cartesian. They are
80	     *    non-negative integer, designating each string `matrix.x.data[i].value`/`matrix.y.data[i].value`.
81	     *    'Xb0', 'Xb2', 'Xa1', 'Xa0' are assigned with the ordinal numbers 0, 1, 2, 3.
82	     *    For every leaf dimension cell, `OrdinalNumber` and `MatrixXYLocator` is the same.
83	     *
84	     *  A cell or pixel point or rect can be determined/located by a pair of `MatrixCoordValueOption`.
85	     *  See also `MatrixBodyCornerCellOption['coord']`.
86	     *
87	     *  - The body cell `bodyS` above can be located by:
88	     *      - `coord: [1, 0]` (`MatrixXYLocator` or `OrdinalNumber`, which is a non-negative integer)
89	     *      - `coord: ['Xb1', 'Yb0']`
90	     *      - `coord: ['Xb1', 0]` (mix them)
91	     *  - The corner cell `cornerQ` above can be located by:
92	     *      - `coord: [-2, -1]` (negative `MatrixXYLocator`)
93	     *      - But it is NOT supported to use `coord: ['Y1_0', 'X1_0']` (XY transposed form) here.
94	     *        It's mathematically sound, but may introduce confusion and unnecessary
95	     *        complexity (consider the 'Xa1' case), and corner locating is not frequently used.
96	     *  - `mergeCells`: Body cells or corner cells can be merged, such as "bodyT" above, an input
97	     *      - The merging can be defined by:
98	     *        `matrix.data[i]: {coord: [['Xb1', 'Xa1'], 'Yb0'], mergeCells: true}`.
99	     *      - Input `['Xa1', 'Yb1']` to `dataToPoint` will get a point in the center of "bodyT".
100	     *      - Input `['Xa1', 'Yb1']` to `dataToLayout` will get a rect of the "bodyT".
101	     *  - If inputing a non-leaf dimension cell to locate, such as `['Xa0', 'Yb0']`,
102	     *      - it returns only according to the center of the dimension cells, regardless of the body span.
103	     *        (therefore, the result can be on the boundary of two body cells.)
104	     *        And the oridinal number assigned to 'Xa0' is 3, thus input `[3, 'Yb0']` get the some result.
105	     *  - The dimension (header) cell can be located by negative `MatrixXYLocator`. For example:
106	     *      - The center of the node 'Ya0' can be located by `[-2, 'Ya0']`.
107	     */
108	    data?: MatrixBodyCornerCellOption[];
109	}
110	export interface MatrixBodyOption extends MatrixBodyCornerBaseOption {
111	}
112	export interface MatrixCornerOption extends MatrixBodyCornerBaseOption {
113	}
