5	} from 'zrender/src/core/util';
6	import Point from 'zrender/src/core/Point';
7	import OrdinalMeta from '../../data/OrdinalMeta';
8	import { NullUndefined, OrdinalNumber } from '../../util/types';
9	import Ordinal from '../../scale/Ordinal';
10	import {
11	    MatrixDimensionModel, MatrixDimensionCellOption, MatrixDimensionCellLooseOption,
12	    MatrixDimensionLevelOption,
13	    MatrixCoordValueOption,
14	} from './MatrixModel';
15	import { WH, XY } from '../../util/graphic';
16	import { ListIterator } from '../../util/model';
17	import { RectLike } from 'zrender/src/core/BoundingRect';
18	import {
19	    createNaNRectLike, setDimXYValue, MatrixCellLayoutInfoType
20	} from './matrixCoordHelper';
21	import { error } from '../../util/log';
22	import { mathMax } from '../../util/number';
