24	
25	export interface MatrixCellLayoutInfo {
26	    type: MatrixCellLayoutInfoType;
27	    // Represents col/row, serves as both id and locator.
28	    // For a `MatrixDimensionCell`:
29	    //  it is `setDimXYValue(new Point(), dimIdx, firstLeafLocator, level - _levels.length)`.
30	    //  e.g., `id[dimIdx]` is `0` or `1` or `2` or `3` if there are at most `4` leaves in the tree.
31	    // For a `MatrixDimensionLevelInfo`:
32	    //  it is `setDimXYValue(new Point(), dimIdx, 0, level - _levels.length)`
33	    //  e.g., `id[1 - dimIdx]` is `-3` or `-2` or `-1` if the tree has `3` levels.
34	    // If negative, locate to corner cells; otherwise, locate to body cells.
35	    id: Point;
36	    // By pixel. Computed left-top x (for x dimension) or y (for y dimension).
37	    // Used to locate.
38	    xy: number;
39	    // By pixel. Computed height (for x dimension) or width (for y dimension).
40	    // Used to locate.
41	    wh: number;
42	    dim: MatrixDim;
43	}
44	
45	
46	export type MatrixXYLocator = MatrixCellLayoutInfo['id']['x'] | MatrixCellLayoutInfo['id']['y'];
47	/**
48	 * [[xmin, xmax], [ymin, ymax]]
49	 * For each internal value, be NaN if invalid or out of boundary (never be null/undefined),
50	 * otherwise must be valid locators.
51	 * @see parseCoordRangeOption
52	 * @see resetXYLocatorRange
53	 */
54	export type MatrixXYLocatorRange = MatrixXYLocator[][] & {__brand: 'MatrixXYLocatorRange'};
55	/**
56	 * [[xmin, xmax], [ymin, ymax]], be `NullUndefined` if illegal.
57	 */
58	export type MatrixXYCellLayoutInfoRange = (MatrixCellLayoutInfo | NullUndefined)[][];
59	
60	export interface MatrixDimensionCell extends MatrixCellLayoutInfo {
61	    // Computed col/row span. Always exists and >= 1.
62	    // `span[XY[dimIdx]]` is actually the leaves count of this subtree.
63	    span: Point;
64	    // Start from 0, tree depth.
65	    level: number;
66	    // It is both `MatrixXYLocator` and `OrdinalNumber` and _cell[index].
67	    firstLeafLocator: MatrixXYLocator;
68	    // Used to fatch its raw value by `matrixDim.getOrdinalMeta().category[ordinal]`,
69	    // or feach cell by `_cells[ordinal]`.
70	    // The ordinal of the leaf nodes is the same as `id.getOnDim(0)` for quick query,
71	    // but not the same for non-leaf nodes.
72	    ordinal: OrdinalNumber;
73	    // Normalized raw option of `matrix.x/y.data[i]`, not include any parents option.
74	    // Never be NullUndefined
75	    option: MatrixDimensionCellOption;
76	    // The layout rect for rendering. Available after matrix coordinate system resizing.
77	    rect: RectLike;
78	}
79	
80	/**
81	 * Computed properties of a certain tree level.
82	 * In most cases this is used to describe level size or locate corner cells.
83	 */
84	export interface MatrixDimensionLevelInfo extends MatrixCellLayoutInfo {
85	    // The raw option of `matrix.levels[i]`
86	    option: MatrixDimensionLevelOption | NullUndefined;
87	}
88	
89	export type MatrixDimPair = {
90	    x: MatrixDim;
91	    y: MatrixDim;
92	};
93	
94	/**
95	 * Lifetime: the same with `MatrixModel`, but different from `coord/Matrix`.
96	 */
97	export class MatrixDim {
98	    // Use it to visit `cell.id` and `cell.span`
99	    readonly dim: 'x' | 'y';
100	    // Must be `0 | 1`, corresponding to 'x' | 'y'
101	    readonly dimIdx: number;
102	
103	    // Under the current definition, every leave corresponds a unit cell,
104	    // and leaves can serve as the locator of cells.
105	    // Therefore make sure:
106	    //  - The first `_leavesCount` elements in `_cells` are leaves.
107	    //  - `_cells[leaf.id[XY[this.dimIdx]]]` is the leaf itself.
108	    //  - Leaves of each subtree are placed together, that is, the leaves of a dimCell are:
109	    //    `this._cells.slice(dimCell.firstLeafLocator, dimCell.span[XY[this.dimIdx]])`
110	    private _cells: MatrixDimensionCell[] = [];
111	
112	    // Can be visited by `_levels[cell.level]` or `_levels[cell.id[1 - dimIdx] + _levels.length]`.
113	    // Items are never be null/undefined after initialized.
114	    private _levels: MatrixDimensionLevelInfo[] = [];
115	
116	    private _leavesCount: number;
117	
118	    private _model: MatrixDimensionModel;
119	    private _ordinalMeta: OrdinalMeta;
120	    // Only for uniformly parsing.
121	    private _scale: Ordinal;
122	
123	    private _uniqueValueGen: ReturnType<typeof createUniqueValueGenerator>;
124	
125	    constructor(dim: 'x' | 'y', dimModel: MatrixDimensionModel) {
126	        this.dim = dim;
127	        this.dimIdx = dim === 'x' ? 0 : 1;
128	        this._model = dimModel;
129	
130	        this._uniqueValueGen = createUniqueValueGenerator(dim);
131	
132	        let dimModelData = dimModel.get('data', true);
133	        if (dimModelData != null && !isArray(dimModelData)) {
134	            if (__DEV__) {
135	                error(`Illegal echarts option - matrix.${this.dim}.data must be an array if specified.`);
136	            }
137	            dimModelData = [];
138	        }
139	        if (dimModelData) {
140	            this._initByDimModelData(dimModelData);
141	        }
142	        else {
143	            this._initBySeriesData();
144	        }
145	    }
146	
147	    private _initByDimModelData(dimModelData: MatrixDimensionCellLooseOption[]) {
148	        const self = this;
149	        const _cells = self._cells;
150	        const _levels = self._levels;
151	        const sameLocatorCellsLists: MatrixDimensionCell[][] = []; // Save for sorting.
152	        let _cellCount = 0;
153	
154	        self._leavesCount = traverseInitCells(dimModelData, 0, 0);
155	
156	        postInitCells();
157	
158	        return;
159	
160	        function traverseInitCells(
161	            dimModelData: MatrixDimensionCellLooseOption[] | NullUndefined,
162	            firstLeafLocator: number,
163	            level: number
164	        ): number {
165	            let totalSpan = 0;
166	            if (!dimModelData) {
167	                return totalSpan;
168	            }
169	
170	            each(dimModelData, (option, optionIdx) => {
171	                let invalidOption = false;
172	                let cellOption: MatrixDimensionCell['option'];
173	                if (isString(option)) {
174	                    cellOption = {value: option};
175	                }
176	                else if (isObject(option)) {
177	                    cellOption = option;
178	                    if (option.value != null && !isString(option.value)) {
179	                        invalidOption = true;
180	                        cellOption = {value: null};
181	                    }
182	                }
183	                else {
184	                    cellOption = {value: null};
185	                    if (option != null) {
186	                        invalidOption = true;
187	                    }
188	                }
189	
190	                if (invalidOption) {
191	                    if (__DEV__) {
192	                        error(`Illegal echarts option - matrix.${self.dim}.data[${optionIdx}]`
193	                            + ' must be `string | {value: string}`.'
194	                        );
195	                    }
196	                }
197	
198	                const cell: MatrixDimensionCell = {
199	                    type: MatrixCellLayoutInfoType.nonLeaf, // Update to leaf later if it's a leaf.
200	                    ordinal: NaN, // Set it later.
201	                    level,
202	                    firstLeafLocator,
203	                    id: new Point(), // Set it in `_initCellsId`.
204	                    span: setDimXYValue(new Point(), self.dimIdx, 1, 1),
205	                    option: cellOption,
206	                    xy: NaN,
207	                    wh: NaN,
208	                    dim: self,
209	                    rect: createNaNRectLike(),
210	                };
211	                _cellCount++;
212	                (sameLocatorCellsLists[firstLeafLocator]
213	                    || (sameLocatorCellsLists[firstLeafLocator] = [])
214	                ).push(cell);
215	
216	                if (!_levels[level]) {
217	                    // Create a level only if at least one cell exists.
218	                    _levels[level] = {
219	                        type: MatrixCellLayoutInfoType.level,
220	                        xy: NaN, wh: NaN, option: null, id: new Point(), dim: self
221	                    };
222	                }
223	
224	                const childrenSpan = traverseInitCells(
225	                    cellOption.children, firstLeafLocator, level + 1
226	                );
227	                const subSpan = Math.max(1, childrenSpan);
228	                cell.span[XY[self.dimIdx]] = subSpan;
229	
230	                totalSpan += subSpan;
231	                firstLeafLocator += subSpan;
232	            });
233	
234	            return totalSpan;
235	        }
236	
237	        function postInitCells() {
238	            // Sort to make sure the leaves are at the beginning, so that
239	            // they can be used as the locator of body cells.
240	            const categories: (string | NullUndefined)[] = [];
241	            while (_cells.length < _cellCount) {
242	                for (let locator = 0; locator < sameLocatorCellsLists.length; locator++) {
243	                    const cell = sameLocatorCellsLists[locator].pop();
244	                    if (cell) {
245	                        cell.ordinal = categories.length;
246	                        const val = cell.option.value;
247	                        categories.push(val);
248	                        _cells.push(cell);
249	                        self._uniqueValueGen.calcDupBase(val);
250	                    }
251	                }
252	            }
253	            self._uniqueValueGen.ensureValueUnique(categories, _cells);
254	
255	            const ordinalMeta = self._ordinalMeta = new OrdinalMeta({
256	                categories: categories,
257	                needCollect: false,
258	                deduplication: false,
259	            });
260	            self._scale = new Ordinal({ordinalMeta});
261	
262	            for (let idx = 0; idx < self._leavesCount; idx++) {
263	                const leaf = self._cells[idx];
264	                leaf.type = MatrixCellLayoutInfoType.leaf;
265	                // Handle the tree level variation: enlarge the span of the leaves to reach the body cells.
266	                leaf.span[XY[1 - self.dimIdx]] = self._levels.length - leaf.level;
267	            }
268	
269	            self._initCellsId();
270	            self._initLevelIdOptions();
271	        }
272	    }
273	
274	    private _initBySeriesData() {
275	        const self = this;
276	        self._leavesCount = 0;
277	        self._levels = [{
278	            type: MatrixCellLayoutInfoType.level,
279	            xy: NaN, wh: NaN, option: null, id: new Point(), dim: self
280	        }];
281	        self._initLevelIdOptions();
282	
283	        const ordinalMeta = self._ordinalMeta = new OrdinalMeta({
284	            needCollect: true,
285	            deduplication: true,
286	            onCollect: (value: unknown, ordinalNumber: number): void => {
287	                const cell = self._cells[ordinalNumber] = {
288	                    type: MatrixCellLayoutInfoType.leaf,
289	                    ordinal: ordinalNumber,
290	                    level: 0,
291	                    firstLeafLocator: ordinalNumber,
292	                    id: new Point(), // Set it in `_initCellsId`.
293	                    span: setDimXYValue(new Point(), self.dimIdx, 1, 1),
294	                    // Theoretically `value` is from `dataset` or `series.data`, so it may be any type.
295	                    // Do not restrict this case for user's convenience, and here simply convert it to
296	                    // string for display.
297	                    option: {value: value + ''},
298	                    xy: NaN,
299	                    wh: NaN,
300	                    dim: self,
301	                    rect: createNaNRectLike(),
302	                };
303	                self._leavesCount++;
304	                self._setCellId(cell);
305	            },
306	        });
307	        self._scale = new Ordinal({ordinalMeta});
308	    }
