310	    private _setCellId(cell: MatrixDimensionCell) {
311	        const levelsLen = this._levels.length;
312	        const dimIdx = this.dimIdx;
313	        setDimXYValue(cell.id, dimIdx, cell.firstLeafLocator, cell.level - levelsLen);
314	    }
