316	    private _initCellsId() {
317	        const levelsLen = this._levels.length;
318	        const dimIdx = this.dimIdx;
319	        each(this._cells, cell => {
320	            setDimXYValue(cell.id, dimIdx, cell.firstLeafLocator, cell.level - levelsLen);
321	        });
