324	    private _initLevelIdOptions() {
325	        const levelsLen = this._levels.length;
326	        const dimIdx = this.dimIdx;
327	        let levelOptionList = this._model.get('levels', true);
328	        levelOptionList = isArray(levelOptionList) ? levelOptionList : [];
329	
330	        each(this._levels, (levelCfg, level) => {
331	            setDimXYValue(levelCfg.id, dimIdx, 0, level - levelsLen);
